    object_property_add_uint32_ptr(obj, "reset-commands", &s->reset_commands, OBJ_PROP_FLAG_READ);
    object_property_add_uint32_ptr(obj, "reset-completions", &s->reset_completions, OBJ_PROP_FLAG_READ);
