    object_property_add_uint32_ptr(obj, "tx-bytes", &s->tx_bytes, OBJ_PROP_FLAG_READ);
    object_property_add_uint32_ptr(obj, "rx-bytes", &s->rx_bytes, OBJ_PROP_FLAG_READ);
